def min_hops(adj, start, target):
    if start == target:
        return 0
    visited = {start}
    queue = [start]
    hops = 0
    while queue:
        hops += 1
        next_level = []
        for node in queue:
            for v in adj[node]:
                if v == target:
                    return hops
                if v not in visited:
                    visited.add(v)
                    next_level.append(v)
        queue = next_level
    return -1


def main():
    V, adj = read_graph()
    start, target = map(int, input().split())
    print(min_hops(adj, start, target))


