def count_components(adj):
    visited = set()
    count = 0
    for start in adj:
        if start not in visited:
            count += 1
            stack = [start]
            visited.add(start)
            while stack:
                node = stack.pop()
                for v in adj[node]:
                    if v not in visited:
                        visited.add(v)
                        stack.append(v)
    return count


