def farthest_hops(adj, start):
    dist = {start: 0}
    queue = [start]
    far = 0
    while queue:
        node = queue.pop(0)
        for v in adj[node]:
            if v not in dist:
                dist[v] = dist[node] + 1
                if dist[v] > far:
                    far = dist[v]
                queue.append(v)
    return far


