def reach_sizes(adj):
    sizes = []
    for start in adj:
        visited = {start}
        stack = [start]
        while stack:
            node = stack.pop()
            for v in adj[node]:
                if v not in visited:
                    visited.add(v)
                    stack.append(v)
        sizes.append(len(visited))
    return sizes


