def count_at_hops(adj, start, k):
    visited = {start}
    level = [start]
    depth = 0
    while level and depth < k:
        next_level = []
        for node in level:
            for v in adj[node]:
                if v not in visited:
                    visited.add(v)
                    next_level.append(v)
        level = next_level
        depth += 1
    return len(level)


def main():
    V, adj = read_graph()
    start, k = map(int, input().split())
    print(count_at_hops(adj, start, k))


